"""Resolve the requested display scope and seal it before Gaussian arithmetic."""
from common import *
from shapely.geometry import shape, mapping, Point
from shapely import vectorized
assert not (C/'procfig_v1.lock.json').exists()
outline=R/'docs/experiments/phd/main_gtjudge_v1/tables/addendum10/c1_outline.geojson'
boxfile=R/'docs/experiments/phd/main_gtjudge_v1/tables/addendum10/c1_boxes.json'
feature=json.loads(outline.read_text())['features'][0];poly=shape(feature['geometry']);buffer=poly.buffer(1)
box=json.loads(boxfile.read_text())['panel1_box_corners_local_xy'];center=np.mean(box,axis=0)
assert poly.covers(Point(center))
survey=PH/'main_design_realchange_survey_v1/PHD-MAIN-DESIGN-REALCHANGE-SURVEY-v1/derived.npz'
dtm=loadz(survey,['dtm'])['dtm'];ix=int(np.floor((center[0]+SHIFT[0]-690700)/.5));iy=int(np.floor((center[1]+SHIFT[1]-5335820)/.5));ground=float(dtm[iy,ix]-SHIFT[2]);assert np.isfinite(ground)
prior=S1/'defs'/SITE/'prior_ALS.npz';v=loadz(prior,['V'])['V'];inside=vectorized.contains(buffer,v[:,0],v[:,1]);top=float(v[inside,2].max())
sources=dict(outline=str(outline),case_box=str(boxfile),ground_dtm=str(survey),prior=str(prior),mvs_points=str(PH/'main_uncert_v1/PHD-MAIN-UNCERT-v1/points'/SITE/'mvs_a_xyz.npy'),target=str(FT/'targets'/f'{STEM}.npz'),seeds=str(FT/'stage1'/STEM/'seeds.npz'),snapshot_initial_fields=str(MODEL/'target_monitor/snapshot_7000.npz'),reference_rows=str(GT/'scenes'/STEM/'rows.npz'),reference_cases=str(GT/'scenes'/STEM/'stage1_cells.npz'),core=str(JA/'core_points'/f'{STEM}.npz'),section=str(R/'docs/experiments/phd/main_gtjudge_v1/figures/addendum6'/f'{CASE}_section_data.json'),result_mesh=str(RS/'addendum3_stage1/meshes'/f'{STEM}__FINALTRAIN_30000/primary.ply'),gravity=str(PH.parent/'p0-audit/data/work/gate_s0/freeze_recovery_v1/P2-GATE-S0-FREEZE-RECOVERY-v1/checkpoints/030-dense_mvs_and_gravity.json'))
for it in [7000,15000,30000]:sources[f'checkpoint_{it}']=str(MODEL/f'jbgs_complete/iteration_{it}/checkpoint.pth')
sources['finaltrain_config']=str(R/'configs/phd/main_finaltrain_v1/finaltrain_v1.json');sources['runtime_lock']=str(R/'configs/phd/main_finaltrain_v1/runtime.lock.json')
sources['initialization_code']=str(R/'src/phd/forks/GeoGS-conf-guided-v1-r23/jbgs_target.py');sources['training_code']=str(R/'src/phd/forks/GeoGS-conf-guided-v1-r23/train.py');sources['seed_code']=str(R/'scripts/phd/main_finaltrain_v1/prepare_inputs.py')
up=np.array(json.loads(Path(sources['gravity']).read_text())['payload']['gravity']['up']);up/=np.linalg.norm(up)
c=dict(task_id='PHD-MAIN-PROCFIG-v1',addendum=1,created_at=now(),scientific_verdict=None,training=False,branch='exp/main-experiment',source_commit=os.environ['PROCFIG_COMMIT'],finaltrain_config_commit='926bf2d1dc8cd994774a985b007f34ed500644b1',training_commit_status='config source_commit plus runtime lock; checkpoint source_sha256 is authoritative code binding',seed=0,fork='GeoGS-conf-guided-v1-r23',site=SITE,prior='ALS',case=CASE,sources=sources,
  scope=dict(building_id=feature['properties']['building_id'],footprint=feature['geometry'],buffered_footprint=mapping(buffer),xy_buffer_m=1,z_min=ground+.3,z_max=top+2,ground_z=ground,old_roof_max_z=top,ground_rule='inherited survey DTM 0.5m cell at exact saved case-box XY centre; no LoD2 Z',ground_cell_iy_ix=[iy,ix],ground_query_xy=center.tolist(),zoom_box_xy=box),
  coordinates=dict(crs='EPSG:25832',local_to_world_translation=SHIFT.tolist(),up=up.tolist()),iterations=[0,7000,15000,30000],input_panel_is_not_a_gaussian_state=True,
  initialization=dict(mode='CPU reconstruction from frozen r23 seeds and immutable snapshot initial fields',reason='r23 initializer requires CUDA tensors, CUDA KNN and random rotations; section 1 is CPU-only',positions='exact seeds.xyz',scale='snapshot_7000.initial_scale immutable initialization record',opacity=.1,rotation='inherited quat_from_normal on saved initialization normal; initial tangent scales are equal so disc geometry is invariant to twist',not_a_resumable_training_checkpoint=True),
  metrics=dict(wall='abs(normal dot frozen up)<0.5',opacity_low=.1,interval_sigma=1.96,interval_edge_m=.001,roof_area='sum exact clipped prior roof triangle areas',lineage_population='initial seeds inside same building scope; descendants counted inside same scope; escaped counts separate',patch_selection='original judge_region in [1,4], unique modal stored GT case 1, old prior z minus median assigned GT z >1m; existing row_owner/source_index columns',comparison='original judge_region 2, unique modal stored GT case 1',prior_near_m=.5,majority_tie='case 1 must be unique winner, inherited majority.py; no tie reassignment',heights='prior centre + prior_height_m*normal; per-patch assigned GT median Z'),
  rendering=dict(azimuth_degrees=list(range(0,360,45)),elevation_degrees=35,width_px=1800,height_px=1400,background='#FCFCFA',scale_bar_m=5,light_direction=[-.35,-.45,.82],shade='0.55+0.45*abs(normal dot unit fixed light)',visibility_tolerance_m=.15,visibility_rule='case1 reference point not occluded by result mesh >0.15m in front; inherited add6 visibility tolerance',styles=dict(a=dict(scale=.6,alpha_threshold=None,opacity='opaque'),b=dict(scale=1.,alpha_threshold=None,opacity='opaque'),c=dict(scale=.6,alpha_threshold=None,opacity='activated_alpha'),d=dict(scale=.6,alpha_threshold=.1,opacity='opaque')),rank_styles={'1':['a','b','c','d'],'2':['a'],'3':['a']},zoom_styles=['a','b','c'],wrong_lineage_always_visible_in_threshold_selection=True,grid_m=.25,colors={'0':'#7FA7D9','2':'#D85A30','1':'#1D9E75','4':'#E8B931','background_released':'#B4B2A9','wrong':'#C2378A'}),
  reading_rules=dict(wrong_coverage_ratio_lt=.1,wrong_old_roof_alpha_median_lt=.1,wall_count_ratio_ge=3,edge_fraction_ge=.01,surface_alignment='human reads section and discs; if stage3 available case1 completeness30000 >=7000',automatic_scientific_decision=False),max_attribution_seconds=1800,stage3='optional after stage1+2 delivery; no waiting for optional mesh',write_roots=['configs/phd/main_procfig_v1','scripts/phd/main_procfig_v1','docs/experiments/phd/main_procfig_v1','PH/main_procfig_v1/PHD-MAIN-PROCFIG-v1'],PH_resolution=str(PH),runtime=dict(image=os.environ['PROCFIG_IMAGE'],python=sys.version,numpy=np.__version__))
dump(C/'procfig_v1.json',c)
dump(C/'procfig_v1.lock.json',dict(at=now(),config_sha256=sha(C/'procfig_v1.json'),phase='before Gaussian metrics, patch selection, or rendering',scientific_verdict=None))
issue('발주문의 outlines.json은 해당 이름으로 없으므로 같은 사례의 덧붙임10 c1_outline.geojson(LoD2 GroundSurface XY, DEBY_LOD2_4959326)과 c1_boxes.json을 사용. 원본을 변경하지 않음.')
issue('지면은 앞 작업 survey DTM 및 Grid 규칙으로 사례 상자 중심의 0.5m 셀을 조회. 건물 범위의 고정 Z 하한은 이 지면+0.3m. PH는 기존 코드와 같은 외부 phase-payloads/phd 별칭.')
issue('0회는 CPU 전용 조건 때문에 CUDA 필수 r23 초기화 전체를 호출하지 않음. 기존 seeds와 snapshot의 불변 initial_scale/normal로 재구성하며 배경 원형 원반의 축 주위 회전은 비유일. 원래 회전 쿼터니언의 바이트 동일성은 확인 불가.')
hashes={}
for label,p in sources.items():
 assert Path(p).is_file(),p;hashes[label]=dict(path=p,sha256=sha(p),bytes=Path(p).stat().st_size)
dump(D/'input_lock.json',dict(at=now(),config_sha256=sha(C/'procfig_v1.json'),sources=hashes,scientific_verdict=None))
print('CONFIG_LOCKED',sha(C/'procfig_v1.json'),feature['properties']['building_id'],ground,top,flush=True)
